describe("slugify", () => {
  test("transforms basic text with special characters", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
  });

  test("converts to lowercase", () => {
    expect(slugify("UPPERCASE")).toBe("uppercase");
    expect(slugify("MixedCase")).toBe("mixedcase");
  });

  test("replaces spaces with hyphens", () => {
    expect(slugify("hello world")).toBe("hello-world");
    expect(slugify("one two three")).toBe("one-two-three");
  });

  test("replaces underscores with hyphens", () => {
    expect(slugify("foo_bar")).toBe("foo-bar");
    expect(slugify("Foo__Bar")).toBe("foo-bar");
  });

  test("removes special characters", () => {
    expect(slugify("user@example.com")).toBe("userexamplecom");
    expect(slugify("Price: $99.99")).toBe("price-9999");
  });

  test("collapses multiple hyphens", () => {
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("foo--bar")).toBe("foo-bar");
  });

  test("trims leading and trailing hyphens", () => {
    expect(slugify("-hello-")).toBe("hello");
    expect(slugify("--start")).toBe("start");
    expect(slugify("end--")).toBe("end");
    expect(slugify("-start-end-")).toBe("start-end");
  });

  test("handles edge cases", () => {
    expect(slugify("")).toBe("");
    expect(slugify("   ")).toBe("");
    expect(slugify("!@#$%")).toBe("");
    expect(slugify("  hello  ")).toBe("hello");
  });

  test("preserves numbers and hyphens", () => {
    expect(slugify("123-456")).toBe("123-456");
  });

  test("applies transformations in correct order", () => {
    expect(slugify("  Hello, World!  ")).toBe("hello-world");
    expect(slugify(" a---b ")).toBe("a-b");
  });
});

