/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Convert text to URL-safe slug.
 * Transforms text to lowercase, replaces spaces and underscores with hyphens,
 * removes special characters, collapses multiple hyphens, and trims edge hyphens.
 */
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\s_]+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "");
}

